#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <sys/types.h>
#include <unistd.h>

#define IMG_MAX_WIDTH 4096
#define IMG_MAX_HEIGHT 4096
#define AUDIT_PATH "/var/log/imgproc/audit.log"
#define WATERMARK_TOKEN_LEN 16

typedef struct {
    uint32_t width;
    uint32_t height;
    uint8_t channels;
    uint8_t *data;
} Image;

typedef struct {
    uint64_t state[4];
} PipelineRNG;

static inline uint64_t rotl(const uint64_t x, int k) {
    return (x << k) | (x >> (64 - k));
}

/* xoshiro256** generator - high quality PRNG */
static uint64_t rng_next(PipelineRNG *rng) {
    const uint64_t result = rotl(rng->state[1] * 5, 7) * 9;
    const uint64_t t = rng->state[1] << 17;
    rng->state[2] ^= rng->state[0];
    rng->state[3] ^= rng->state[1];
    rng->state[1] ^= rng->state[2];
    rng->state[0] ^= rng->state[3];
    rng->state[2] ^= t;
    rng->state[3] = rotl(rng->state[3], 45);
    return result;
}

static void rng_seed_from_entropy(PipelineRNG *rng, const void *seed_material, size_t len) {
    /* SplitMix64 seeding from provided material */
    uint64_t base_seed = 0;
    const uint8_t *p = (const uint8_t *)seed_material;
    for (size_t i = 0; i < len && i < 8; i++) {
        base_seed |= ((uint64_t)p[i]) << (i * 8);
    }
    for (int i = 0; i < 4; i++) {
        base_seed += 0x9e3779b97f4a7c15ULL;
        uint64_t z = base_seed;
        z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
        z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
        rng->state[i] = z ^ (z >> 31);
    }
}

static int init_pipeline_rng(PipelineRNG *rng) {
    /* Gather entropy: combine pid, time, and address space layout */
    struct {
        pid_t pid;
        time_t t;
        void *stack_addr;
    } entropy_block;

    entropy_block.pid = getpid();
    entropy_block.t = time(NULL);
    entropy_block.stack_addr = &entropy_block;

    rng_seed_from_entropy(rng, &entropy_block, sizeof(entropy_block));
    return 0;
}

static void generate_watermark_token(PipelineRNG *rng, char *token_out) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyz0123456789";
    for (int i = 0; i < WATERMARK_TOKEN_LEN; i++) {
        uint64_t r = rng_next(rng);
        token_out[i] = charset[r % (sizeof(charset) - 1)];
    }
    token_out[WATERMARK_TOKEN_LEN] = '\0';
}

static int audit_log_operation(const char *operation, const char *token,
                               uint32_t width, uint32_t height) {
    FILE *f = fopen(AUDIT_PATH, "a");
    if (!f) return -1;
    fprintf(f, "[%ld] op=%s token=%s dim=%ux%u\n",
            (long)time(NULL), operation, token, width, height);
    fclose(f);
    return 0;
}

static int apply_noise_reduction(Image *img, PipelineRNG *rng) {
    if (!img || !img->data) return -1;

    /* Dithered noise reduction: use RNG for sub-pixel threshold decisions */
    size_t total = (size_t)img->width * img->height * img->channels;
    for (size_t i = 0; i < total; i++) {
        uint64_t r = rng_next(rng);
        uint8_t threshold = (uint8_t)(r & 0x0F);
        if (img->data[i] < threshold) {
            img->data[i] = 0;
        }
    }
    return 0;
}

static int embed_watermark(Image *img, PipelineRNG *rng, const char *token) {
    if (!img || !img->data || !token) return -1;

    /* Embed token bits into LSBs at pseudo-random positions */
    size_t total_pixels = (size_t)img->width * img->height;
    size_t token_bits = strlen(token) * 8;

    for (size_t bit = 0; bit < token_bits; bit++) {
        uint64_t pos = rng_next(rng) % total_pixels;
        size_t byte_idx = pos * img->channels;
        uint8_t token_byte = token[bit / 8];
        uint8_t token_bit = (token_byte >> (bit % 8)) & 1;
        img->data[byte_idx] = (img->data[byte_idx] & 0xFE) | token_bit;
    }
    return 0;
}

int process_image_pipeline(uint8_t *raw_data, uint32_t width, uint32_t height,
                           uint8_t channels) {
    if (width > IMG_MAX_WIDTH || height > IMG_MAX_HEIGHT) return -1;
    if (channels < 1 || channels > 4) return -1;
    if (!raw_data) return -1;

    Image img = { .width = width, .height = height,
                  .channels = channels, .data = raw_data };

    PipelineRNG rng;
    init_pipeline_rng(&rng);

    char token[WATERMARK_TOKEN_LEN + 1];
    generate_watermark_token(&rng, token);

    audit_log_operation("noise_reduce", token, width, height);
    if (apply_noise_reduction(&img, &rng) != 0) return -1;

    audit_log_operation("watermark", token, width, height);
    if (embed_watermark(&img, &rng, token) != 0) return -1;

    audit_log_operation("complete", token, width, height);
    return 0;
}
